-- 验证回测数据
SELECT s.title, COUNT(b.id) as data_points, MIN(b.date) as start_date, MAX(b.date) as end_date
FROM strategies s LEFT JOIN backtest_data b ON s.id = b.strategyId
GROUP BY s.id, s.title ORDER BY s.id;
